import sys
import heapq

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal(n, edges, skip_edge=None):
    parent = list(range(n))
    rank = [0] * n
    cost = 0
    for e, u, v in edges:
        if (u, v) == skip_edge or (v, u) == skip_edge:
            continue
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            cost += e
    return cost

def max_energy_for_first_corridor(n, m, corridors):
    edges = []
    for a, b, e in corridors:
        edges.append((e, a - 1, b - 1))
    edges.sort()
    original_cost = kruskal(n, edges)
    first_edge = edges[0]
    max_e = 0
    for e in range(first_edge[0], -1, -1):
        cost_with_skipped = kruskal(n, edges, skip_edge=(first_edge[1], first_edge[2]))
        if cost_with_skipped == original_cost:
            max_e = e
            break
    return max_e

